<script lang="ts">
  import { uiLanguage, createUiTranslator } from "../i18n"
  const tr = $derived(createUiTranslator($uiLanguage))

  import { onMount, type Snippet } from 'svelte';
  import type { SettingsSection } from '../shell/navigation';
  import { findSettings, settingsSections } from './settings-catalog';
  import { AudioLines, Search } from '@lucide/svelte';
  import SidebarFooter from '../shell/SidebarFooter.svelte';
  import ShellTopbar from '../shell/ShellTopbar.svelte';
  let { section, onsection, onback, backLabel, children, onhome, onsearch, onprojects, onrefresh, refreshing, runtimeState, collapsed, ontoggle }: { section: SettingsSection; onsection: (section: SettingsSection) => void; onback: () => void; backLabel: string; children: Snippet; onhome: () => void; onsearch: () => void; onprojects: () => void; onrefresh: () => void; refreshing: boolean; runtimeState: string; collapsed: boolean; ontoggle: () => void } = $props();
  onMount(() => document.querySelector<HTMLElement>('.settings-shell .shell-topbar strong')?.focus());
  let query = $state('');
  const sections = $derived(findSettings(query, tr));

  function keydown(event: KeyboardEvent) { if (event.key === 'Escape' && !event.defaultPrevented && !document.querySelector('.modal-backdrop,dialog[open],[role=listbox]')) { event.preventDefault(); onback(); } }
</script>

<svelte:window onkeydown={keydown}/>
<div class="settings-shell" class:sidebar-hidden={collapsed}><aside class="settings-navigation sidebar-surface" aria-label={tr("Nawigacja ustawień")}><div class="sidebar-header"><button class="sidebar-brand" aria-label={tr("Seventy Seven Labs — pulpit")} onclick={onhome}><AudioLines size={24}/><span>{tr("Seventy Seven Labs")}</span></button><label class="sidebar-search sidebar-search-field"><Search size={16}/><input type="search" aria-label={tr("Filtruj ustawienia")} placeholder={tr("Szukaj…")} autocomplete="off" bind:value={query}/></label></div><div class="settings-nav-body"><nav aria-label={tr("Sekcje ustawień")}>{#each sections as group (group.title)}<h6 class="settings-group">{tr(group.title)}</h6>{#each group.items as item (item.id)}<button class="shell-nav-row" class:current={section === item.id} aria-current={section === item.id ? 'page' : undefined} title={item.label} onclick={() => onsection(item.id)}><span class="shell-nav-destination"><item.icon size={17}/><span>{tr(item.label)}</span></span></button>{/each}{/each}{#if !sections.length}<p class="settings-no-results">{tr("Brak pasujących ustawień.")}</p>{/if}</nav></div><SidebarFooter {runtimeState} settings onsettings={() => {}} onmodels={() => onsection('engine')} {onprojects} {onrefresh} {refreshing} {onback} {backLabel}/></aside><main class="settings-main"><ShellTopbar title={tr("Ustawienia / {value0}", {value0: tr(settingsSections.find(item => item.id === section)?.label || '')})} {ontoggle} {collapsed}/><div class="settings-scroll"><div class="settings-content">{@render children()}</div></div></main></div>
