  .settings-group{margin:14px 10px 4px;font-size:var(--ui-text-10);font-weight:600;letter-spacing:.6px;text-transform:uppercase;color:var(--muted)}.settings-group:first-child{margin-top:0}
  .settings-shell{position:fixed;inset:0;z-index:80;display:grid;background:var(--background);color:var(--foreground)}.settings-nav-body{flex:1;min-height:0;overflow-y:auto;scrollbar-gutter:stable}.settings-no-results{padding:12px;font-size:var(--ui-text-12);color:var(--muted)}.settings-navigation .shell-nav-destination>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.settings-navigation nav{display:flex;flex-direction:column;gap:0}.settings-navigation nav>button{height:var(--nav-row-height);min-height:var(--nav-row-height);padding:0;text-align:left}.settings-main{min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden}.settings-scroll{scrollbar-gutter:stable;overflow-y:auto;flex:1;min-height:0}.settings-content{max-width:820px;margin:auto;padding:30px 34px 48px}.settings-content :global(.page-body.narrow),.settings-content :global(.settings-page),.settings-content :global(.ai-settings),.settings-content :global(.shortcuts-page),.settings-content :global(.appearance-panel){max-width:none;margin:0;padding:0}.settings-content :global(:not(.p-page)>.page-heading){margin-bottom:32px}.settings-content :global(h1){font-size:var(--ui-text-22);font-weight:600;letter-spacing:-.5px}.settings-content :global(.ai-settings>header){align-items:flex-start;margin-bottom:32px}.settings-content :global(.ai-settings>header>svg){display:none}.settings-content :global(.ai-settings>header p),.settings-content :global(.page-heading p){font-size:var(--ui-text-13);line-height:1.5;margin-top:7px}@media(max-width:650px){.settings-content{padding:22px 18px 32px}}
